type Session struct {
    mu sync.Mutex
    m  map[Key]*Customer
}

func (s *Session) Get(id Key) (*Customer, error) {
    s.mu.Lock()
    defer s.mu.Unlock()
    if c, ok := s.m[id]; ok {
        return c, nil
    }
    c, err := loadCustomer(id)          // query only on miss
    if err != nil {
        return nil, err
    }
    s.m[id] = c
    return c, nil
}
